// @pit: {"label": "Rewrite precedence test with it.each; fix boolean check; format; rerun check"}
async ({ workspace: { read, edit }, shell: { exec } }) => {
  const s = await read("src/context-files.ts", { format: "raw" });
  await edit("src/context-files.ts", { revision: s.revision, changes: [{ kind: "replaceFile", content: s.content.replace("return paths.filter((_, index) => files[index]);", "return paths.filter((_, index) => files[index] === true);") }] });
  const t = await read("src/context-files.test.ts", { format: "raw" });
  const start = t.content.indexOf(`	it("takes the first of pi's names in each directory"`);
  const end = t.content.indexOf(`	it("skips a directory named like a context file"`);
  const nt = t.content.slice(0, start) + `	const names = [
		"AGENTS.override.md",
		"AGENTS.md",
		"AGENTS.MD",
		"CLAUDE.md",
		"CLAUDE.MD",
	];
	// Each name, next to the name after it, which loses (CLAUDE.MD, the last, is alone).
	it.each(names.map((name, index) => [name, names.slice(index + 1, index + 2)]))(
		"takes %s before %j, in pi's order of names",
		async (name, after) => {
			const root = tempDir();
			write(join(root, name), name);
			for (const other of after) {
				write(join(root, other), "loses");
			}
			const context = await loadProjectContext(options({ cwd: root }));
			expect(context.files.map((file) => [file.label, file.content])).toStrictEqual([
				[name, name],
			]);
		},
	);

` + t.content.slice(end);
  await edit("src/context-files.test.ts", { revision: t.revision, changes: [{ kind: "replaceFile", content: nt }] });
  await exec("npx oxfmt src docs README.md 2>&1 | tail -3", { timeoutMs: 60000 });
  const c = await exec("npm run check 2>&1 | grep -v '✓' | tail -40", { timeoutMs: 280000 });
  return c.stdout;
}
